    if F.saving then coins = math.min(coins, (S.cps or 0) * 1.5) elseif on("rb_on") then coins = math.max(coins, (S.cps or 0) * 1.5) end
    local list = PT.eggList()
    if want ~= "Best I Can Afford" then
        for _, e in ipairs(list) do if e.name == want then return e end end
        for _, e in ipairs(Workspace:FindFirstChild("Eggs") and Workspace.Eggs:GetChildren() or {}) do if e.Name == want then return { name = e.Name, model = e, price = (D.Eggs[e.Name] or {}).Price or math.huge } end end
        return
    end
    local best
    for _, e in ipairs(list) do if coins >= e.price * 3 then best = e end end
    PT.visit = PT.missing(M.unlockedIslands(), list, coins, best)
    best = best or list[1]
    PT.sticky, PT.stickyUntil = best, os.clock() + 120
    return best
end
function PT.reserve()
    if not on("eg_on") then return 0 end
