function PT.hatch()
    if (M.pending or 0) > 0 and os.clock() - (M.lastFire or 0) < 4 then return true end
    M.pending = 0
    if PT.visit then
        local island = PT.visit
        PT.visit, PT.visitAt[island] = nil, os.clock()
        local pos = PT.anchor(island)
        if pos then
            S.task = __T["Loading "] .. island .. __T[" eggs"]
            local t = os.clock()
            while os.clock() - t < 2.5 and RUNNING do M.tp(pos + Vector3.new(0, 4, 0)) task.wait(0.2) end
            PT.sticky = nil
            return true
        end
    end
    if F.rbWant then return false end
    local e = PT.pick()
    if not e then S.task = __T["Saving for an egg"] return false end
    local unit = PT.unitPrice(e)
    local coins = M.coins() - val("eg_keep", 0)
    local n = coins >= unit * 3 and 3 or (coins >= unit and 1 or 0)
    if n == 0 then S.task = __T["Saving for "] .. e.name .. __T[" egg"] return false end
    local pn, pl = PT.storage()
    if pn >= pl then S.task = __T["Pet storage full"] S.gerr = __T["Pet storage full"] return false end
    if pl - pn < 3 then n = 1 end
    local r = M.root()
    local ep = (e.model and e.model.Parent and e.model:GetPivot().Position) or e.pos
    if not ep then return false end
    if r and (r.Position - ep).Magnitude > 12 then M.tp(ep + Vector3.new(0, 3, 6)) task.wait(1.1) end
    S.task = "Hatching " .. e.name
    F.seq += 1
    fire("EggService", "EggHatchRequested", { Egg = e.name, Count = n, Auto = false, Seq = F.seq })
    M.lastFire = os.clock()
    M.pending = (M.pending or 0) + 1
    return true
end
