            local lim = ({ ["1 in 100"] = 100, ["1 in 1K"] = 1000, ["1 in 10K"] = 10000, ["1 in 100K"] = 100000, ["1 in 1M"] = 1000000 })[val("eg_notify", "1 in 10K")] or 10000
