function PT.craft()
    local d = M.data()
    local eq = {}
    for _, id in pairs((d.Pets or {}).Equipped or {}) do eq[tostring(id)] = true end
    local groups = {}
    for id, p in pairs((d.Pets or {}).Owned or {}) do
        if type(p) == "table" and (p.Tier == nil or p.Tier == "Normal") and not p.Locked and not p.Mutation and not PT.gone[tostring(p.Id or id)] and not (on("cr_keepeq") and eq[tostring(p.Id or id)]) then
            local k = tostring(p.Name)
            groups[k] = groups[k] or {}
            table.insert(groups[k], p.Id or id)
        end
    end
    local need = val("cr_count", 6)
    for name, ids in pairs(groups) do
        if #ids >= need then
            local mach = PT.machine("Golden")
            if not mach then return false end
            EV.settle()
            M.near(mach, 4)
            task.wait(0.3)
            local sel = {}
            for i = 1, need do sel[i] = ids[i] end
            fire("MachineService", "MachineCraftRequested", { Action = "Craft", Machine = "Golden", PetIds = sel })
            S.task = __T["Crafting golden "] .. name
            return true
        end
    end
end
