function PT.clean()
    local n, lim = PT.storage()
    if n < lim - val("pc_free", 15) then return false end
    local d = M.data()
    local eq = {}
    for _, id in pairs((d.Pets or {}).Equipped or {}) do eq[tostring(id)] = true end
    local allow = val("pc_rar", nil)
    local counts = {}
    for _, p in pairs(d.Pets.Owned) do if type(p) == "table" and (p.Tier == nil or p.Tier == "Normal") then counts[p.Name] = (counts[p.Name] or 0) + 1 end end
    local cand = {}
    local goldOk = PT.noDiamond or not on("pe_diamond")
    local minEq = math.huge
    for id, p in pairs(d.Pets.Owned) do if type(p) == "table" and eq[tostring(p.Id or id)] then minEq = math.min(minEq, tonumber(p.Power) or 0) end end
    for id, p in pairs(d.Pets.Owned) do
        local pid = type(p) == "table" and tostring(p.Id or id)
        local normal = type(p) == "table" and (p.Tier == nil or p.Tier == "Normal")
        local weak = pid and minEq < math.huge and (tonumber(p.Power) or 0) < minEq and (normal or p.Tier == "Golden" or p.Tier == "Diamond")
        if pid and not PT.gone[pid] and ((normal and not p.Mutation) or (goldOk and p.Tier == "Golden" and not p.Mutation) or weak) and not p.Locked and not eq[pid] and (weak or type(allow) ~= "table" or allow[p.Rarity]) then
            cand[#cand + 1] = { id = pid, pw = tonumber(p.Power) or 0, c = (normal and not p.Mutation) and (counts[p.Name] or 0) or 99, g = not normal }
        end
    end
    table.sort(cand, function(a, b)
        if a.g ~= b.g then return not a.g end
        if (a.c >= 3) ~= (b.c >= 3) then return a.c < 3 end
        return a.pw < b.pw
    end)
    local want = math.max(0, n - (lim - val("pc_free", 15) - 15))
    local ids = {}
    for i = 1, math.min(want, #cand, 40) do ids[#ids + 1] = cand[i].id end
    if #ids == 0 then S.gerr = __T["Pet storage full"] return false end
    PT.batch = (PT.batch or 0) + 1
    fire("PetService", "PetActionRequested", { Action = "Delete", PetIds = ids, Batch = PT.batch })
    for _, id in ipairs(ids) do PT.gone[id] = true end
    S.deleted = (S.deleted or 0) + #ids
    LOG("deleted", #ids)
    return true
end
