function EV.popEvents()
    local now = Workspace:GetServerTimeNow()
    for _, svc in ipairs({ "BalloonPartyService", "PigsCouldFlyService" }) do
        local s = D.get(svc)
        local ok, list = pcall(function() return s and s:GetActive() end)
        if ok and type(list) == "table" then
            local live = {}
            for _, v in pairs(list) do
                if type(v) == "table" and v.Uid and not EV.hitDone[v.Uid] and typeof(v.Origin) == "Vector3" and type(v.LaunchedAt) == "number" then
                    local age = now - v.LaunchedAt
                    if age >= 0 and age < 19 then live[#live + 1] = { b = v, p = v.Origin + Vector3.new(0, (tonumber(v.Rise) or 0) * age, 0), need = math.max(1, (tonumber(v.Hits) or 1) - (tonumber(v.Taken) or 0)) } end
                end
            end
            if #live > 0 then
                local best, bn = live[1], 0
                for _, x in ipairs(live) do
                    local n = 0
                    for _, y in ipairs(live) do if (x.p - y.p).Magnitude < 120 then n += 1 end end
                    if n > bn then best, bn = x, n end
                end
                S.task = svc == "BalloonPartyService" and __T["Popping balloons"] or __T["Hitting pigs"]
                local spot = best.p - Vector3.new(0, 8, 0)
                M.tp(spot)
                task.wait(0.35)
                for _, x in ipairs(live) do
                    if (x.p - best.p).Magnitude < 120 then
                        EV.hitDone[x.b.Uid] = true
                        for _ = 1, x.need do
                            M.tp(spot + Vector3.new(0, (tonumber(best.b.Rise) or 0) * 0.5, 0))
                            pcall(function() s.Hit:Fire(x.b.Uid) end)
                            task.wait(0.12)
                        end
                        S.pops = (S.pops or 0) + 1
                    end
                end
                return true
            end
        end
    end
end
