function EV.fishZone(spot, from, m)
    local FC, Sim = D.Fish, D.FSim
    local pond = m and m:FindFirstChild("Pond")
    if not (Sim and pond) then return end
    local rect = { X = pond.Position.X, Z = pond.Position.Z, RadiusX = pond.Size.X / 2, RadiusZ = pond.Size.Z / 2 }
    local t = Workspace:GetServerTimeNow()
    local best, bl
    for i, key in ipairs(spot.Zones or {}) do
        local z = FC.Zones and FC.Zones[key]
        if z and (tonumber((gcall(Sim.ZoneShown, spot, i, t))) or 0) > 0 then
            local x, zz = gcall(Sim.ZonePosition, spot, i, rect, t)
            if x and zz then
                local dist = Vector2.new(x - from.X, zz - from.Z).Magnitude
                if dist >= FC.Cast.MinDistance and dist <= FC.Cast.MaxDistance - 2 and (not bl or z.Luck > bl) then best, bl = Vector3.new(x, 0, zz), z.Luck end
            end
        end
    end
    return best, t
end
function EV.fish()
    local FC = D.Fish
    if not FC or not FC.RodId then return false end
    local d = M.data()
    local fd = d.Fishing
    if type(fd) ~= "table" then return false end
    local spot = EV.fishSpot(d)
    if not spot then return false end
    local baits = fd.Bait or {}
    local total = 0
    for _, n in pairs(baits) do total += tonumber(n) or 0 end
    local rods = fd.Rods or {}
    local slots = math.min(spot.Slots or 3, tonumber((gcall(FC.RodLimit, d))) or FC.MaxRods or 3)
    local work = fd.PendingRing ~= nil or fd.Gifted ~= true or next(fd.Bowl or {}) ~= nil
    for i = 1, slots do
        local r = rods[FC.RodId(spot.Id, i)]
        if (r and #(r.Hooked or {}) > 0) or (not r and total > 0) then work = true end
    end
    if D.FSim and D.MR and on("ev_fishbuy") then
        local gems = M.gems() - val("sk_keep", 0)
        local ok, offers = pcall(D.FSim.ShopOffers, D.FSim.ShopWindow(math.floor(Workspace:GetServerTimeNow())), fd.Shop)
        for _, o in ipairs(ok and offers or {}) do
            local price = o.Taps and gcall(D.MR.Price, d, o.Taps)
            if price and gems * 0.02 >= price and not (EV.fishBuyWait[o.Id] and os.clock() < EV.fishBuyWait[o.Id]) then
                local r = call("FishingService", "Buy", o.Id)
                if type(r) == "table" and r.Success then say(__T["Bought "] .. tostring(o.Id)) work = true break end
                EV.fishBuyWait[o.Id] = os.clock() + 600
            end
        end
    end
    if not work then return false end
    local m = gcall(FC.FindSpotModel, spot.Id)
    if not m then
        local p = EV.fishPos[spot.Id] or (spot.Id == "HalloweenPond" and Vector3.new(-1733, -509, -1751))
        if not p then return false end
        EV.settle()
        local t = os.clock()
        while not m and os.clock() - t < 3 and RUNNING do M.tp(p) task.wait(0.25) m = gcall(FC.FindSpotModel, spot.Id) end
        if not m then return false end
    end
    local stand = m:FindFirstChild("Stand")
    local at = (stand and stand:GetPivot().Position or m:GetPivot().Position) + Vector3.new(0, 4, 0)
    EV.fishPos[spot.Id] = at
    EV.settle()
    S.task = __T["Fishing"]
    local t = os.clock()
    while os.clock() - t < 0.8 and RUNNING do M.tp(at) task.wait(0.1) end
    if fd.Gifted ~= true then call("FishingService", "ClaimGift") end
    local pr = fd.PendingRing
    if type(pr) == "table" and FC.Rings then
        local new, cur = FC.Rings[pr.Name or ""], FC.Rings[(type(fd.Ring) == "table" and fd.Ring.Name) or ""]
        call("FishingService", "ClaimRing", (not cur or (new and (new.Order or 0) > (cur.Order or 0))) and "replace" or "keep")
    end
    for i = 1, slots do
        local id = FC.RodId(spot.Id, i)
        local r = (M.data().Fishing.Rods or {})[id]
        local n = 0
        while r and #(r.Hooked or {}) > 0 and n < 4 and RUNNING do
            n += 1
            local res = call("FishingService", "Reel", id)
            if type(res) ~= "table" or not res.Success then break end
            S.fish = (S.fish or 0) + 1
            if type(res.Pet) == "string" then say(__T["Fished a "] .. res.Pet) end
            task.wait(0.3)
            r = (M.data().Fishing.Rods or {})[id]
        end
    end
    baits = M.data().Fishing.Bait or {}
    for i = 1, slots do
        local id = FC.RodId(spot.Id, i)
        if not (M.data().Fishing.Rods or {})[id] then
            local bk, bl
            for k, c in pairs(baits) do
                local b = FC.Baits[k]
                if (tonumber(c) or 0) > 0 and b and (not bl or (b.Luck or 1) > bl) then bk, bl = k, b.Luck or 1 end
            end
            if not bk then break end
            local mount = gcall(FC.FindRodMount, m, i)
            local from = mount and mount.Position or at
            local p, pt = EV.fishZone(spot, from, m)
            if not p then local c = m:FindFirstChild("Cast") p = c and c.Position end
            if not p then break end
            local load = math.min(tonumber(baits[bk]) or 0, FC.Cast.Load or 10)
            local res = call("FishingService", "Cast", id, bk, load, { X = p.X, Z = p.Z, T = pt or Workspace:GetServerTimeNow() })
            if type(res) == "table" and res.Success then say(__T["Cast "] .. bk .. __T[" in "] .. tostring(res.Zone or __T["pond"])) baits[bk] -= load end
            task.wait(0.3)
        end
    end
    if next(M.data().Fishing.Bowl or {}) then call("FishingService", "Collect") end
    return true
end
