    for item, kind in pairs({ RainDial = "Rain", AcidDial = "Acid", BloodMoonDial = "BloodMoon" }) do
        if (tonumber(owned[item]) or 0) > 0 and not active["Event_" .. (kind == "Rain" and "RainyDay" or kind) .. "_Active"] then
