    for _, name in ipairs({ "PetLevels10", "GoldenApple", "RainbowStrawberry", "DragonFruit", "SecretFruit", "BagOfTreats" }) do
        local n = tonumber(owned[name]) or 0
        if n > 0 and eq[1] and not (EV.treatWait and os.clock() < EV.treatWait) then
            local r = call("ItemService", "UseOnPet", { Item = name, PetId = tostring(eq[1]), Amount = n })
