function EV.breakTarget()
    local CS = game:GetService("CollectionService")
    local r = M.root()
    local best, bd
    local function consider(m)
        if m:IsDescendantOf(Workspace) and (tonumber(m:GetAttribute("BreakableHealth")) or 1) > 0 then
            local d = r and (m:GetPivot().Position - r.Position).Magnitude or 0
            if not bd or d < bd then best, bd = m, d end
        end
    end
    for _, tag in ipairs({ "MysteryEgg", "MeteorRock" }) do for _, m in ipairs(CS:GetTagged(tag)) do consider(m) end end
    for _, m in ipairs(Workspace:GetChildren()) do
        if m:IsA("Model") and m:GetAttribute("BreakableType") == "RainbowChest" and m:GetAttribute("BreakableOwner") == lp.UserId then consider(m) end
    end
    return best
end
