    local eq = {}
    for _, id in pairs((d.Pets or {}).Equipped or {}) do eq[tostring(id)] = true end
    local pet, slot, bp
    for id, p in pairs((d.Pets or {}).Owned or {}) do
        local pid = type(p) == "table" and tostring(p.Id or id)
        if pid and eq[pid] and not (EV.enWait[pid] and os.clock() < EV.enWait[pid]) then
            local s = (not want[tostring(p.Enchant)] and 1) or (p.Enchant2 ~= nil and not want[tostring(p.Enchant2)] and 2) or nil
            if s and (not bp or (tonumber(p.Power) or 0) > bp) then pet, slot, bp = p, s, tonumber(p.Power) or 0 end
        end
    end
    if not pet then UI.enMsg = "Team enchanted" return false end
    local z = EV.enZone()
    if not z then
        local key = "shadowrelm"
        local anchor = EV.enPos
        if not anchor then for id, pos in pairs(Workspace:FindFirstChild("ShinyStars") and Workspace.ShinyStars:GetAttributes() or {}) do if typeof(pos) == "Vector3" and id:lower():gsub("%d", "") == key then anchor = pos break end end end
        if not anchor then return false end
        EV.settle()
        local t = os.clock()
        while not z and os.clock() - t < 3 and RUNNING do M.tp(anchor + Vector3.new(0, 4, 0)) task.wait(0.25) z = EV.enZone() end
        if not z then return false end
    end
    local list = {}
    for n in pairs(want) do list[#list + 1] = n end
    EV.settle()
    S.task = __T["Enchanting "] .. tostring(pet.Name)
    local pid = tostring(pet.Id)
    local done, res = false, nil
    local svc = D.get("EnchantService")
    local conn = svc and svc.AutoEvent and svc.AutoEvent:Connect(function(x) if type(x) == "table" and x.Kind == "Stop" then done, res = true, x end end)
    local t = os.clock()
    while os.clock() - t < 0.6 and RUNNING do M.tp(z.Position) task.wait(0.1) end
    call("EnchantService", "SetFilters", list)
    local r = call("EnchantService", "AutoStart", { PetId = pid, Slot = slot })
    if type(r) == "table" and r.Success then
        t = os.clock()
        while not done and os.clock() - t < 45 and RUNNING do M.tp(z.Position) task.wait(0.2) end
        if not done then call("EnchantService", "AutoStop") end
    else
        EV.enWait[pid] = os.clock() + 600
        LOG("enchant", type(r) == "table" and r.Reason or r)
    end
    if conn then conn:Disconnect() end
    call("EnchantService", "Claim")
    task.wait(0.3)
    PT.equipBest()
    if res and res.Reason == "Matched" then
        S.enchants = (S.enchants or 0) + 1
        say(tostring(pet.Name) .. ": " .. tostring(res.Enchant))
    elseif res then EV.enWait[pid] = os.clock() + 300 end
    return true
end
