function EV.trick()
    local cfg = D.TT
    if not cfg then return false end
    local data = M.data().TrickOrTreat or {}
    local now = Workspace:GetServerTimeNow()
    local hid
    for _, id in ipairs(cfg.Houses or {}) do
        local t = tonumber(data[id]) or 0
        local ready = tonumber((gcall(cfg.ReadyAt, t))) or (t + (cfg.Cooldown or 14400))
        if now >= ready and not (EV.knocked[id] and os.clock() < EV.knocked[id]) then hid = id break end
    end
    if not hid then EV.trickFast = false return false end
    local z = EV.pads(cfg)[hid]
    if not z then
        local pos = EV.padPos[hid] or EV.bossPos or Vector3.new(-1733, -509, -1751)
        EV.settle()
        local t = os.clock()
        while not z and os.clock() - t < 3 and RUNNING do M.tp(pos) task.wait(0.25) z = EV.pads(cfg)[hid] end
        if not z then
            for id, p in pairs(EV.padPos) do if not z and id ~= hid then M.tp(p) task.wait(0.6) z = EV.pads(cfg)[hid] end end
        end
        if not z then EV.knocked[hid] = os.clock() + 120 return false end
    end
    EV.settle()
    S.task = __T["Trick or treating"]
    local t = os.clock()
    while os.clock() - t < 0.6 and RUNNING do M.tp(z.Position + Vector3.new(0, 2, 0)) task.wait(0.1) end
    local r = call("TrickOrTreatService", "Knock", hid)
    if type(r) == "table" and r.Success then say(__T["Trick or treat!"]) EV.knocked[hid] = nil EV.trickFast = true
    else EV.knocked[hid] = os.clock() + 300 LOG("knock", hid, type(r) == "table" and (r.Error or r.Reason) or r) end
    return true
end
